const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value ?? "").replace(/[&<>'"]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[character]));
const api = async (path, options = {}) => { const response = await fetch(path, options); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || body.detail || "请求失败，请稍后重试。"); return body; };
const percent = (value) => `${(Number(value) * 100).toFixed(1)}%`;
const stepNames = { load_model: "准备分类模型", validate_input: "输入校验", read_text: "读取文本", parse_document: "解析文档", prepare_text: "文本整理", classify_text: "调用分类模型", select_candidates: "候选排序", accept_prediction: "确认预测", review_candidates: "复核候选", query_category: "查询类别", generate_result: "生成结果" };
const liveSteps = new Map();

function setMessage(message, isError = false) { const node = $("#request-message"); node.textContent = message; node.classList.toggle("error", isError); }
function setBusy(form, busy, message) { form.querySelector("button[type=submit]").disabled = busy; if (message) setMessage(message); }
function updateTextCount() { $("#text-count").textContent = `${$("#text-input").value.length.toLocaleString()} / 200,000`; }
function setMode(mode) { document.querySelectorAll(".mode-tab").forEach((tab) => { const active = tab.dataset.mode === mode; tab.classList.toggle("active", active); tab.setAttribute("aria-selected", String(active)); }); $("#text-form").hidden = mode !== "text"; $("#file-form").hidden = mode !== "file"; $("#file-form").classList.toggle("hidden", mode !== "file"); }
function statusClass(data) { if (data.confidence_status === "low") return ["low", "置信度较低"]; if (data.confidence_status === "normal") return ["", "分类完成"]; return ["waiting", "等待输入"]; }
function renderWorkflow(steps) { if (!steps.length) return; $("#steps-list").innerHTML = steps.map((step, index) => { const state = step.status === "failed" ? "failed" : step.status === "running" ? "running" : step.status === "done" ? "done" : "pending"; return `<li class="${state}"><span>${index + 1}</span><div><strong>${escapeHtml(stepNames[step.name] || step.name || "智能体处理")}</strong><small>${escapeHtml(step.detail || (state === "running" ? "处理中…" : "已完成"))}</small></div></li>`; }).join(""); }
function beginWorkflow(message) { liveSteps.clear(); liveSteps.set("server:prepare", { step_id: "server:prepare", name: "load_model", status: "running", detail: message }); $("#result-section").classList.remove("is-empty"); $("#result-status").className = "status-tag working"; $("#result-status").textContent = "智能体执行中"; $("#duration").textContent = message; $("#result-message").textContent = "执行节点将随模型工作实时更新。"; renderWorkflow([...liveSteps.values()]); }
function receiveStep(step) { const key = step.step_id || `${step.name}:${liveSteps.size}`; if (step.name !== "load_model" && liveSteps.has("server:prepare")) { const loading = liveSteps.get("server:prepare"); liveSteps.set("server:prepare", { ...loading, status: "done", detail: "分类模型已就绪" }); } liveSteps.set(key, step); renderWorkflow([...liveSteps.values()]); $("#duration").textContent = step.detail || "智能体正在执行下一步…"; }
async function streamApi(path, options, onEvent) { const response = await fetch(path, options); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.error || body.detail || "请求失败，请稍后重试。"); } if (!response.body) throw new Error("浏览器未能建立实时连接，请刷新后重试。"); const reader = response.body.getReader(), decoder = new TextDecoder(); let buffer = "", result; while (true) { const { value, done } = await reader.read(); buffer += decoder.decode(value || new Uint8Array(), { stream: !done }); let boundary; while ((boundary = buffer.indexOf("\n\n")) !== -1) { const block = buffer.slice(0, boundary); buffer = buffer.slice(boundary + 2); let event = "message", data = ""; block.split(/\r?\n/).forEach((line) => { if (line.startsWith("event:")) event = line.slice(6).trim(); if (line.startsWith("data:")) data += line.slice(5).trim(); }); if (data) { const payload = JSON.parse(data); onEvent(event, payload); if (event === "result") result = payload; } } if (done) break; } if (!result) throw new Error("分类连接提前结束，请重试。"); return result; }
function showFailure(payload) { $("#result-section").classList.remove("is-empty"); $("#result-status").className = "status-tag failed"; $("#result-status").textContent = "执行失败"; $("#result-message").textContent = payload.error || "分类服务未返回结果。"; $("#duration").textContent = "请检查输入或模型服务后重试。"; if (payload.steps?.length) renderWorkflow(payload.steps); }

function renderResult(payload) {
  const data = payload.data || {}, prediction = data.prediction || {}, top1 = prediction.top1 || {}, [kind, label] = statusClass(data);
  $("#result-section").classList.remove("is-empty"); $("#top1-code").textContent = top1.code || "—"; $("#top1-name").textContent = top1.name || "未返回类别名称";
  $("#result-status").className = `status-tag ${kind}`; $("#result-status").textContent = label; $("#confidence-number").textContent = top1.confidence == null ? "—" : percent(top1.confidence);
  $("#confidence-fill").style.width = `${Math.max(0, Math.min(100, Number(top1.confidence || 0) * 100))}%`; $("#result-message").textContent = data.message || "分类完成。模型分数不等同于实际正确率。";
  $("#candidate-count").textContent = `Top-${data.returned_top_k || (prediction.topk || []).length}`;
  $("#topk-list").innerHTML = (prediction.topk || []).map((item) => `<li><b>${escapeHtml(item.code)}</b><span>${escapeHtml(item.name)}</span><em>${percent(item.confidence)}</em></li>`).join("") || "<li><b>—</b><span>无候选结果</span><em>—</em></li>";
  $("#metadata").innerHTML = [`模型 ${prediction.model_type || "—"}`, `候选 ${data.returned_top_k || 0}`, data.input?.truncated ? "输入已截断" : `耗时 ${Math.round(data.duration_ms || 0)} ms`].map((item) => `<span>${escapeHtml(item)}</span>`).join("");
  $("#duration").textContent = data.duration_ms ? `本次工作流耗时 ${Math.round(data.duration_ms)} ms` : "任务提交后将展示每一步的处理状态。";
  const steps = payload.steps || []; if (steps.length) renderWorkflow(steps);
  $("#result-section").scrollIntoView({ behavior: "smooth", block: "center" });
}
async function submitText(event) { event.preventDefault(); const text = $("#text-input").value.trim(); if (text.length < 10) return setMessage("请输入至少 10 个字符的医学文献内容。", true); const form = event.currentTarget; setBusy(form, true, "智能体已启动，正在实时返回执行进度。"); beginWorkflow("正在准备分类模型…"); try { const result = await streamApi("/api/classify/stream", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text, top_k: Number($("#text-topk").value) }) }, (type, payload) => { if (type === "status" || type === "step") receiveStep(payload); }); if (result.success) { renderResult(result); setMessage("分类完成。结果与执行过程已更新。"); } else { showFailure(result); setMessage(result.error || "分类失败，请重试。", true); } } catch (error) { showFailure({ error: error.message }); setMessage(error.message, true); } finally { setBusy(form, false); } }
async function submitFile(event) { event.preventDefault(); const file = $("#file-input").files[0]; if (!file) return setMessage("请选择 TXT、PDF 或 DOCX 文献文件。", true); const form = event.currentTarget; setBusy(form, true, "智能体已启动，正在实时解析文件。"); beginWorkflow("正在接收并解析上传文献…"); try { const data = new FormData(); data.append("file", file); const result = await streamApi(`/api/classify/file/stream?top_k=${$("#file-topk").value}`, { method: "POST", body: data }, (type, payload) => { if (type === "status" || type === "step") receiveStep(payload); }); if (result.success) { renderResult(result); setMessage("文件分类完成。结果与执行过程已更新。"); } else { showFailure(result); setMessage(result.error || "分类失败，请重试。", true); } } catch (error) { showFailure({ error: error.message }); setMessage(error.message, true); } finally { setBusy(form, false); } }
function horizontalBars(items) { const max = Math.max(...items.map(([, value]) => Number(value)), 1); $("#length-chart").innerHTML = items.map(([label, value]) => `<div class="bar-row"><span>${escapeHtml(label)}</span><div class="bar-track"><i class="bar-fill" style="width:${Number(value) / max * 100}%"></i></div><b>${Number(value).toLocaleString()}</b></div>`).join(""); }
function verticalBars(categories) { const max = Math.max(...categories.map((item) => Number(item.count)), 1); $("#category-chart").innerHTML = categories.map((item) => `<div class="vertical-bar" title="${escapeHtml(item.name)}：${item.count}"><small>${item.count}</small><i style="height:${Math.max(8, item.count / max * 100)}%"></i><b>${escapeHtml(item.code)}</b></div>`).join(""); }
function matrixView(matrixData) { const labels = (matrixData?.labels || []).slice(0, 12), matrix = (matrixData?.matrix || []).slice(0, 12).map((row) => row.slice(0, 12)); const max = Math.max(...matrix.flat(), 1); let html = '<span class="matrix-label"></span>'; html += labels.map((label) => `<span class="matrix-label" title="${escapeHtml(label)}">${escapeHtml(label.replace("R", ""))}</span>`).join(""); matrix.forEach((row, rowIndex) => { html += `<span class="matrix-label y" title="${escapeHtml(labels[rowIndex])}">${escapeHtml(labels[rowIndex].replace("R", ""))}</span>`; row.forEach((value, columnIndex) => { const opacity = value ? Math.max(.13, value / max) : 0; html += `<span class="matrix-cell" title="真实 ${escapeHtml(labels[rowIndex])} / 预测 ${escapeHtml(labels[columnIndex])}：${value}" style="background:rgba(35,124,120,${opacity})"></span>`; }); }); $("#confusion-matrix").innerHTML = html; }
async function loadDashboard() { try { const [statistics, metrics] = await Promise.all([api("/api/statistics"), api("/api/metrics")]); const ds = statistics.dataset, split = statistics.split; $("#summary-cards").innerHTML = [[ds.total, "清洗后文献"], [ds.label_count, "模型支持类别"], [split.train, "训练样本数"], [split.test, "测试样本数"]].map(([value, label]) => `<article class="metric-card"><span>${label}</span><strong>${Number(value).toLocaleString()}</strong></article>`).join(""); horizontalBars(Object.entries(ds.text_length_histogram || {})); verticalBars((statistics.categories || []).slice(0, 8)); $("#metrics-table").innerHTML = metrics.models.map((model) => `<tr><td>${escapeHtml(model.model_type.toUpperCase())} v20</td><td>${percent(model.accuracy)}</td><td>${percent(model.f1_macro)}</td><td>${Number(model.inference_time_per_sample_ms).toFixed(2)} ms</td></tr>`).join(""); matrixView(metrics.confusion_matrices?.medbert_v20); } catch (error) { $("#summary-cards").innerHTML = `<p class="request-message error">无法读取统计数据：${escapeHtml(error.message)}</p>`; } }
async function checkHealth() { try { const health = await api("/api/health"); $("#health").textContent = health.status === "ok" ? "服务运行正常" : "服务状态异常"; $("#health").className = `health ${health.status === "ok" ? "ok" : "down"}`; } catch { $("#health").textContent = "服务未连接"; $("#health").className = "health down"; } }
function enableReveals() { const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add("visible"); observer.unobserve(entry.target); } }), { threshold: .08 }); document.querySelectorAll(".reveal").forEach((node) => observer.observe(node)); }
document.querySelectorAll(".mode-tab").forEach((tab) => tab.addEventListener("click", () => setMode(tab.dataset.mode)));
$("#text-form").addEventListener("submit", submitText); $("#file-form").addEventListener("submit", submitFile); $("#text-input").addEventListener("input", updateTextCount); $("#clear-text").addEventListener("click", () => { $("#text-input").value = ""; updateTextCount(); $("#text-input").focus(); }); $("#file-input").addEventListener("change", (event) => { const file = event.target.files[0], zone = $("#upload-zone"), detail = $("#file-detail"); zone.classList.toggle("has-file", Boolean(file)); $("#upload-title").textContent = file ? "已选择文献文件" : "选择或拖入文献文件"; $("#file-name").textContent = file ? file.name : "支持 TXT、PDF、DOCX，最大 10 MiB"; detail.hidden = !file; detail.textContent = file ? `${(file.name.split(".").pop() || "file").toUpperCase()} · ${(file.size / 1024 / 1024).toFixed(2)} MiB · 点击可更换文件` : ""; });
updateTextCount(); enableReveals(); checkHealth(); loadDashboard();
